from math import log
V = lambda x: (2*x - 1) * log(x / (1 - x))      # 가치 함수
def per_kg(xp, xf=0.00711, xt=0.0025):
    F = (xp - xt) / (xf - xt)                     # kgU 원료 / kgU 제품
    T = F - 1                                     # 꼬리(열화우라늄)
    return F, V(xp) + T * V(xt) - F * V(xf)       # (원료, SWU)
for xp in (0.045, 0.05, 0.1975):
    F, S = per_kg(xp)
    print(f"{xp:.2%}: 원료 {F:.1f} kgU, {S:.1f} SWU")
F, S = per_kg(0.1975)                              # HALEU 1 kg 비용(슬라이드 가정)
cost = {"채광": F / 0.848 * 2.2046 * 67, "변환": F * 92,
        "농축": S * 300, "재변환": 10, "가공": 10_000}
tot = sum(cost.values())
for k, v in cost.items():
    print(f"{k} ${v:,.0f} ({v/tot:.0%})")
print(f"합계 ${tot:,.0f}/kgU")
